// Fixed-point Panda FK and robot tables (fx_fk_gen.c is generated by tools/gen_fx_fk.py).
#pragma once
#include <stdint.h>

#define FX_N_SPHERES     70     // 59 fine + 11 link bounding spheres
#define FX_N_OUTER       11
#define FX_N_SELF_OUTER  21
#define FX_N_SELF_INNER  690

extern const int fx_fk_frac;                                   // F: FK values are Q(F) metres
extern const float fx_sphere_r[FX_N_SPHERES];
extern const uint8_t fx_outer[FX_N_OUTER];                     // VAMP check order
extern const uint8_t fx_outer_kid_off[FX_N_OUTER + 1];
extern const uint8_t fx_outer_kids[59];
extern const uint8_t fx_self_outer[FX_N_SELF_OUTER][2];
extern const uint16_t fx_self_off[FX_N_SELF_OUTER + 1];
extern const uint8_t fx_self_inner[FX_N_SELF_INNER][2];

// Joint angles (s16, 2^-12 rad) -> sphere centres in the base frame, Q(F) metres
void fx_fk_base(const int16_t *x, int64_t c[FX_N_SPHERES][3]);
// Reference FK in double with exact sin/cos (validation only)
void fx_fk_ref(const double *x, double c[FX_N_SPHERES][3]);
